GAME_HTML = '<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;background:#080e1c;color:#dceaf5;font-family:system-ui,sans-serif}#wrap{position:relative;max-width:1100px;margin:auto}canvas{display:block;width:100%;aspect-ratio:16/9;background:#0b1428;outline:none;touch-action:none}#bar{display:flex;gap:10px;flex-wrap:wrap;padding:10px;background:#121f32;font-size:12px}button{background:#1f364b;color:#e0f8ff;border:1px solid #48667d;border-radius:6px;padding:10px;cursor:pointer}#touch{display:flex;justify-content:space-between;padding:8px;gap:8px;background:#111d2e}#touch div{display:flex;gap:8px}#touch button{min-width:48px;touch-action:none;user-select:none}#msg{color:#8fe3ec;flex:1;min-width:200px}</style></head><body><div id="wrap"><canvas id="c" width="1100" height="620" tabindex="0" aria-label="야간 운송 와이어 액션 게임. 화면을 클릭한 뒤 키보드로 조작하세요."></canvas><div id="bar"><span id="msg"></span><button id="start">시작 / 다시 시작</button><button id="sound">소리 켜기</button><button id="pause">일시정지</button></div><div id="touch"><div><button data-k="a">◀</button><button data-k="d">▶</button><button data-k=" ">점프</button></div><div><button id="hook">와이어</button><button data-k="shift">대시</button><button data-k="e">상호작용</button></div></div></div><script>\n\'use strict\';\nconst c=document.getElementById(\'c\'),x=c.getContext(\'2d\'),msg=document.getElementById(\'msg\');\nconst W=1100,H=620,END=4700;let keys={},mouse={x:700,y:150},cam=0,t=0,last=0,acc=0,mode=\'title\',rope=null,shake=0,particles=[],audio=null,sound=false,deaths=0,ending=\'\',checkpoint=0;\nconst platforms=[{x:-100,y:520,w:650,h:150},{x:680,y:470,w:290,h:200},{x:1080,y:390,w:270,h:300},{x:1470,y:500,w:330,h:180},{x:1930,y:420,w:340,h:260},{x:2420,y:510,w:260,h:170},{x:2840,y:410,w:340,h:270},{x:3330,y:490,w:330,h:200},{x:3830,y:400,w:310,h:280},{x:4330,y:500,w:600,h:200}];\nconst anchors=[{x:420,y:240},{x:800,y:190},{x:1150,y:130},{x:1550,y:210},{x:1950,y:140},{x:2370,y:180},{x:2790,y:140},{x:3210,y:170},{x:3650,y:130},{x:4050,y:160},{x:4460,y:190}];\nconst chips=[{x:1190,y:350},{x:2110,y:380},{x:2990,y:370}];const stations=[{x:1550,y:500},{x:2990,y:410}];let got=new Set(),saved=new Set();\nlet p={};\nfunction reset(){p={x:100,y:470,vx:0,vy:0,w:22,h:34,ground:false,dash:0,cd:0,face:1};got.clear();saved.clear();checkpoint=0;deaths=0;rope=null;particles=[];cam=0;t=0;ending=\'\';mode=\'play\';keys={};c.focus();}\nfunction beep(f=220,d=.08){if(!sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type=\'triangle\';o.frequency.setValueAtTime(f,audio.currentTime);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.start();o.stop(audio.currentTime+d);}catch(e){sound=false;}}\nfunction burst(px,py,color,n=15){for(let i=0;i<n;i++)particles.push({x:px,y:py,vx:(Math.random()-.5)*250,vy:(Math.random()-.5)*250,life:.3+Math.random()*.4,color});}\nfunction die(){deaths++;shake=12;burst(p.x,p.y,\'#ff537f\',25);beep(80,.2);const sp=checkpoint===2?{x:3000,y:350}:checkpoint===1?{x:1570,y:440}:{x:100,y:470};Object.assign(p,sp,{vx:0,vy:0,dash:0,cd:0});rope=null;}\nfunction attach(){if(mode!==\'play\')return;if(rope){rope=null;beep(180);return;}let best=null,score=1e9;for(const a of anchors){const dist=Math.hypot(a.x-p.x,a.y-p.y);const cursor=Math.hypot(a.x-(mouse.x+cam),a.y-mouse.y);if(dist<440&&dist>25&&a.y<p.y+30&&cursor<score){best=a;score=cursor;}}if(best){rope={x:best.x,y:best.y,len:Math.hypot(best.x-p.x,best.y-p.y)};beep(600);}else beep(100);}\nfunction jump(){if(p.ground||rope){if(rope){rope=null;p.vy=Math.min(p.vy,-380);}else p.vy=-570;p.ground=false;burst(p.x,p.y+18,\'#60e7ed\',9);beep(410);}}\nfunction dash(){if(p.cd<=0){p.dash=.14;p.cd=.8;p.vx=p.face*850;p.vy=0;burst(p.x,p.y,\'#ffcd75\',12);beep(800);}}\nfunction interact(){for(let i=0;i<stations.length;i++){let s=stations[i];if(Math.abs(p.x-s.x)<95&&Math.abs(p.y-(s.y-30))<95){saved.add(i);checkpoint=Math.max(checkpoint,i+1);beep(500);burst(s.x,s.y-35,\'#9affc6\');}}\nif(p.x>4490){ending=got.size===3&&saved.size===2?\'黎明 / 새벽의 신호\':saved.size===2?\'救出 / 마지막 운송\':\'離脱 / 홀로 도착한 밤\';mode=\'end\';beep(700,.4);}}\nfunction press(k){if(mode!==\'play\')return;if(k===\' \'||k===\'w\'||k===\'arrowup\')jump();if(k===\'shift\')dash();if(k===\'e\')interact();if(k===\'q\')attach();}\nwindow.addEventListener(\'keydown\',e=>{let k=e.key.toLowerCase();if([\' \',\'arrowup\',\'arrowdown\',\'arrowleft\',\'arrowright\'].includes(k))e.preventDefault();if(k===\'escape\'){mode=mode===\'play\'?\'pause\':mode===\'pause\'?\'play\':mode;return;}if(!keys[k])press(k);keys[k]=true;});\nwindow.addEventListener(\'keyup\',e=>keys[e.key.toLowerCase()]=false);\nwindow.addEventListener(\'blur\',()=>{keys={};if(mode===\'play\')mode=\'pause\';});\nc.addEventListener(\'pointermove\',e=>{let r=c.getBoundingClientRect();mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height;});\nc.addEventListener(\'pointerdown\',e=>{c.focus();if(mode===\'title\'){reset();return;}if(e.pointerType===\'mouse\')attach();});\nfor(let b of document.querySelectorAll(\'[data-k]\')){b.addEventListener(\'pointerdown\',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);let k=b.dataset.k;if(!keys[k])press(k);keys[k]=true;});for(let ev of [\'pointerup\',\'pointercancel\',\'lostpointercapture\'])b.addEventListener(ev,()=>keys[b.dataset.k]=false);}\ndocument.getElementById(\'hook\').onclick=()=>{mouse={x:p.x-cam+180,y:100};attach();};document.getElementById(\'start\').onclick=reset;document.getElementById(\'sound\').onclick=()=>{sound=!sound;document.getElementById(\'sound\').textContent=sound?\'소리 끄기\':\'소리 켜기\';beep();};document.getElementById(\'pause\').onclick=()=>{mode=mode===\'play\'?\'pause\':mode===\'pause\'?\'play\':mode;c.focus();};\nfunction update(dt){if(mode!==\'play\')return;t+=dt;let dir=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);if(dir)p.face=dir;p.cd=Math.max(0,p.cd-dt);p.dash=Math.max(0,p.dash-dt);\nif(!p.dash){p.vx+=dir*(p.ground?1900:1050)*dt;p.vx*=Math.exp(-(p.ground&&!dir?10:1.2)*dt);p.vx=Math.max(-650,Math.min(650,p.vx));p.vy+=1280*dt;}\nif(rope){if(keys.w||keys.arrowup)rope.len=Math.max(65,rope.len-150*dt);if(keys.s||keys.arrowdown)rope.len=Math.min(440,rope.len+150*dt);}\n// Axis-separated collision. The player position denotes body center.\np.x+=p.vx*dt;for(let b of platforms){if(p.x+11>b.x&&p.x-11<b.x+b.w&&p.y+17>b.y+1&&p.y-17<b.y+b.h){p.x=p.vx>0?b.x-11:b.x+b.w+11;p.vx=0;}}\np.y+=p.vy*dt;p.ground=false;for(let b of platforms){if(p.x+10>b.x&&p.x-10<b.x+b.w&&p.y+17>b.y&&p.y-17<b.y+b.h){if(p.vy>=0){p.y=b.y-17;p.ground=true;}else p.y=b.y+b.h+17;p.vy=0;}}\nif(rope){let dx=p.x-rope.x,dy=p.y-rope.y,d=Math.hypot(dx,dy);if(d>rope.len){let nx=dx/d,ny=dy/d;let tx=rope.x+nx*rope.len,ty=rope.y+ny*rope.len;const blocked=platforms.some(b=>tx+11>b.x&&tx-11<b.x+b.w&&ty+17>b.y&&ty-17<b.y+b.h);if(blocked)rope=null;else{p.x=tx;p.y=ty;let dot=p.vx*nx+p.vy*ny;if(dot>0){p.vx-=dot*nx;p.vy-=dot*ny;}}}}\np.x=Math.max(12,Math.min(END+100,p.x));\nfor(let i=0;i<chips.length;i++)if(!got.has(i)&&Math.hypot(p.x-chips[i].x,p.y-chips[i].y)<40){got.add(i);burst(p.x,p.y,\'#ffdf83\');beep(950);}\n// Telegraphing scanning beams. Dash phases through an active beam.\nfor(let bx of [1760,2610,3520,4200]){let phase=(t+bx/300)%4;if(phase>2.9&&phase<3.65&&Math.abs(p.x-bx)<18&&!p.dash&&p.y>195)die();}\nif(p.y>710)die();cam+=(Math.max(0,Math.min(END-W+160,p.x-W*.35))-cam)*Math.min(1,dt*5);shake*=Math.exp(-12*dt);\nfor(let a of particles){a.x+=a.vx*dt;a.y+=a.vy*dt;a.vy+=300*dt;a.life-=dt;}particles=particles.filter(a=>a.life>0);\n}\nfunction text(str,px,py,size=16,color=\'#dbeafa\'){x.fillStyle=color;x.font=`${size}px system-ui`;x.fillText(str,px,py);}\nfunction rect(px,py,w,h,col){x.fillStyle=col;x.fillRect(px,py,w,h);}\nfunction draw(){x.setTransform(1,0,0,1,0,0);rect(0,0,W,H,\'#0b1428\');let g=x.createLinearGradient(0,0,0,H);g.addColorStop(0,\'#091020\');g.addColorStop(.7,\'#26304c\');g.addColorStop(1,\'#13283e\');x.fillStyle=g;x.fillRect(0,0,W,H);\nx.fillStyle=\'#819ab0\';x.beginPath();x.arc(855-cam*.025,88,37,0,7);x.fill();\nfor(let layer=0;layer<3;layer++){let par=.12+layer*.13;for(let i=-2;i<40;i++){let bx=i*150-cam*par;let bh=100+((i*71+layer*97+9000)%190);let by=520-bh+layer*8;rect(bx,by,108,bh+200,[\'#131d33\',\'#19253d\',\'#1c2e45\'][layer]);for(let r=0;r<5;r++)for(let col=0;col<4;col++)if((r+col+i)%3)rect(bx+12+col*22,by+15+r*24,5,8,layer===2?\'#4b6b78\':\'#2c4057\');if(i%4===0){rect(bx+18,by+40,27,90,\'#784b6a\');text(\'夜\',bx+21,by+67,20,\'#feb19e\');text(\'便\',bx+21,by+96,20,\'#feb19e\');}}}\nx.save();x.translate(-cam+(Math.random()-.5)*shake,(Math.random()-.5)*shake);\nfor(let b of platforms){rect(b.x,b.y,b.w,b.h,\'#111c2e\');rect(b.x,b.y,b.w,5,\'#55b5b9\');rect(b.x,b.y+7,b.w,10,\'#274357\');for(let q=b.x+15;q<b.x+b.w;q+=44){rect(q,b.y+30,23,6,\'#263952\');rect(q,b.y+62,9,4,\'#65728a\');}}\nfor(let a of anchors){let near=Math.hypot(a.x-p.x,a.y-p.y)<440;x.strokeStyle=near?\'#6bf3ed\':\'#49617c\';x.lineWidth=2;x.beginPath();x.arc(a.x,a.y,near?10:7,0,7);x.stroke();rect(a.x-3,a.y-3,6,6,near?\'#b4ffef\':\'#526278\');x.strokeStyle=\'#2d4156\';x.beginPath();x.moveTo(a.x,a.y-10);x.lineTo(a.x,a.y-85);x.stroke();}\nfor(let bx of [1760,2610,3520,4200]){let ph=(t+bx/300)%4;rect(bx-12,175,24,14,\'#b7476b\');if(ph>2.2&&ph<3.65){x.globalAlpha=ph>2.9?.85:.23;rect(bx-5,190,10,520,\'#ff517d\');x.globalAlpha=1;if(ph<2.9)text(\'!\',bx-5,160,22,\'#ff9da3\');}}\nfor(let i=0;i<chips.length;i++)if(!got.has(i)){let a=chips[i];x.save();x.translate(a.x,a.y+Math.sin(t*3)*5);x.rotate(Math.PI/4);rect(-7,-7,14,14,\'#ffdb8c\');x.restore();}\nfor(let i=0;i<stations.length;i++){let a=stations[i];rect(a.x-16,a.y-42,32,42,saved.has(i)?\'#427c75\':\'#805d75\');text(saved.has(i)?\'구조 완료 · 체크포인트\':\'E · 생존자 구조\',a.x-70,a.y-60,13,saved.has(i)?\'#9affc6\':\'#ffd3d3\');}\nrect(4570,340,60,160,\'#1d5363\');rect(4580,350,40,150,\'#6ab7b5\');text(\'E · 전송 게이트\',4515,320,16,\'#b3fff4\');\nif(rope){x.strokeStyle=\'#7af9ee\';x.lineWidth=2;x.beginPath();x.moveTo(p.x,p.y-5);x.lineTo(rope.x,rope.y);x.stroke();}\nif(mode!==\'title\'){// Original compact pixel courier, drawn with crisp rectangles.\nlet px=Math.round(p.x),py=Math.round(p.y);if(p.dash){for(let i=1;i<5;i++){x.globalAlpha=.22/i;rect(px-p.face*i*20-10,py-15,20,31,\'#73f6ed\');}x.globalAlpha=1;}\nrect(px-9,py-12,18,22,\'#c0d0d7\');rect(px-8,py-23,17,13,\'#222b42\');rect(px+(p.face>0?0:-7),py-20,9,4,\'#7cfff1\');rect(px-11,py-11,22,7,\'#fc947f\');rect(px-p.face*26,py-10,20,5,\'#d65e73\');let step=p.ground?Math.sin(t*Math.abs(p.vx)*.07)*5:3;rect(px-8,py+9,6,9+step,\'#4d7386\');rect(px+3,py+9,6,9-step,\'#4d7386\');}\nfor(let a of particles){x.globalAlpha=Math.max(0,a.life);rect(a.x,a.y,3,3,a.color);}x.globalAlpha=1;x.restore();\n// Rain is visual only and does not affect physics.\nx.strokeStyle=\'#87a9c126\';x.lineWidth=1;for(let i=0;i<65;i++){let rx=(i*79+t*90)%W,ry=(i*137+t*420)%H;x.beginPath();x.moveTo(rx,ry);x.lineTo(rx-5,ry+15);x.stroke();}\nrect(20,18,400,72,\'#091321dd\');text(\'NIGHT COURIER / 야간 운송\',35,43,18,\'#b8fcf0\');text(`기록 ${got.size}/3   구조 ${saved.size}/2   추락 ${deaths}   대시 ${p.cd>0?\'충전 중\':\'준비\'}`,35,70,14,\'#cad4e3\');\nif([\'title\',\'pause\',\'end\'].includes(mode)){rect(0,0,W,H,\'#060d1bd9\');let title=mode===\'title\'?\'야간 운송\':mode===\'pause\'?\'연결 대기 중\':ending;text(title,100,210,42,\'#c0fff3\');if(mode===\'title\'){text(\'비가 멎기 전에, 마지막 생존자에게 도착하라.\',104,255,21);text(\'A/D 이동 · SPACE 점프 · 마우스 클릭 또는 Q 와이어 연결/해제\',104,310,16);text(\'W/S 와이어 길이 · SHIFT 대시 · E 구조/게이트 · ESC 일시정지\',104,343,16);text(\'빛나는 고리에 연결한 뒤 좌우로 가속하세요. 기록 3개와 생존자 2명이 결말을 바꿉니다.\',104,390,15,\'#a1c6d6\');text(\'화면을 클릭하거나 아래 시작 버튼을 누르세요.\',104,445,19,\'#ffc887\');}else if(mode===\'end\'){let desc=saved.size===2?(got.size===3?\'당신은 모두를 구했고, 도시가 숨긴 기록도 되찾았다.\':\'모두가 게이트를 통과했다. 그러나 도시의 비밀은 밤에 남았다.\'):\'당신은 도착했다. 뒤에 남은 사람들의 신호가 아직 깜박인다.\';text(desc,104,270,20);text(`수집 ${got.size}/3 · 구조 ${saved.size}/2 · 추락 ${deaths} · ${Math.floor(t)}초`,104,325,17,\'#ffd28a\');text(\'시작 / 다시 시작 버튼으로 다른 결말에 도전하세요.\',104,380,17);}else text(\'ESC 또는 일시정지 버튼으로 계속\',104,275,20);}\nmsg.textContent=mode===\'play\'?(p.x>4450?\'게이트 근처에서 E를 눌러 결말을 확인하세요.\':rope?\'와이어 연결 중 · W/S 길이 조절 · SPACE 도약 · 클릭/Q 해제\':\'하늘색 고리 가까이에서 클릭/Q · 생존자 앞에서 E로 체크포인트 활성화\'):\'가로 화면 권장 · 키보드 조작 전 게임 화면을 클릭하세요.\';\n}\nfunction frame(now){if(!last)last=now;let dt=Math.min((now-last)/1000,.06);last=now;acc+=dt;let count=0;while(acc>=1/120&&count<8){update(1/120);acc-=1/120;count++;}draw();requestAnimationFrame(frame);}p={x:100,y:470,vx:0,vy:0,cd:0};requestAnimationFrame(frame);\n</script></body></html>'
components.html(GAME_HTML, height=790, scrolling=True)
with st.expander("조작과 플레이 안내"):
    st.markdown("""
- **PC 권장**: 게임 화면을 먼저 클릭하세요. A/D 또는 좌우 방향키로 이동합니다.
- **점프**: Space. 공중 와이어 연결 중 누르면 연결을 끊고 도약합니다.
- **와이어**: 마우스를 고리 쪽으로 향하고 클릭하거나 Q. 다시 누르면 해제합니다.
  연결 가능한 범위는 440픽셀입니다. W/S 또는 위/아래 방향키로 줄 길이를 조절합니다.
- **대시**: Shift. 붉은 스캔 빔은 예고 후 켜집니다. 대시 중에는 통과할 수 있습니다.
- **구조/종료**: 생존자 또는 마지막 게이트 근처에서 E.
- 생존자 구조 시 체크포인트가 활성화됩니다. 추락해도 수집품은 유지됩니다.
- 기록 3개와 생존자 2명의 구조 여부에 따라 **세 가지 결말**이 있습니다.
- 아래 터치 버튼으로도 조작할 수 있지만 정밀한 와이어 조작은 키보드·마우스를 권장합니다.
- 소리는 기본 꺼짐입니다. 직접 켠 뒤에만 합성 효과음을 재생합니다.
- 별도 서버 저장 기능은 없으며 새로고침하면 진행이 사라집니다.

상용 게임 전체 분량이 아닌 **플레이 가능한 단일 스테이지 프로토타입**입니다.
특정 작품의 캐릭터·스토리·이미지·음원을 사용하지 않습니다.
""")
